// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.*;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class NativeKernelGroupingProofTest {
	private static NativeTermAuthority identity() {
		NativeTermAuthority authority = mock(NativeTermAuthority.class);
		when(authority.supportsCanonicalTermKeys()).thenReturn(true);
		when(authority.canonicalTermKey(anyLong())).thenAnswer(call -> call.getArgument(0));
		return authority;
	}

	private static LmdbNativeKernelIr.Kernel kernel(LmdbNativeKernelIr.Node... tail) {
		var pipeline = new ArrayList<LmdbNativeKernelIr.Node>();
		pipeline.add(new LmdbNativeKernelIr.SipDomainProbe(0, 0, 0, 1, -1, null, false));
		pipeline.addAll(List.of(tail));
		return new LmdbNativeKernelIr.Kernel(3, pipeline,
				new LmdbNativeKernelIr.Emit(new int[] { 0, 1, 2 }, false, LmdbNativeKernelIr.OutputMods.none()));
	}

	private static int prove(LmdbNativeKernelIr.Kernel kernel, long[] domain,
			NativeTermAuthority authority, boolean serialCompiled, boolean callbacks) {
		var domains = new LmdbNativeKernelBindings.BoundDomains(new long[][] { domain }, new int[] { 0 },
				new int[] { domain.length });
		return NativeKernelGrouping.rootSlot(kernel, new int[] { 4, 5, 6 }, domains, authority,
				NativeCancellationToken.forSource(null), serialCompiled, callbacks);
	}

	@Test
	void nestedOptionalKeepsImmutableRoot() {
		var nested = new LmdbNativeKernelIr.LeftGroup(List.of(new LmdbNativeKernelIr.Probe(1,
				LmdbNativeKernelIr.Operand.col(0), 2)), new int[] { 2 }, new int[0]);
		assertEquals(4, prove(kernel(new LmdbNativeKernelIr.LeftGroup(List.of(nested))),
				new long[] { 1, 2, 3 }, identity(), true, false));
	}

	@Test
	void duplicateDescendingAndUnboundDomainsDecline() {
		for (long[] domain : new long[][] { { 1, 1, 2 }, { 2, 1 }, { -1, 1 }, { 0, 1 } })
			assertEquals(-1, prove(kernel(), domain, identity(), true, false));
	}

	@Test
	void canonicalAliasAndMissingAuthorityDecline() {
		var aliases = identity();
		when(aliases.canonicalTermKey(3)).thenReturn(1L);
		assertEquals(-1, prove(kernel(), new long[] { 1, 2, 3 }, aliases, true, false));
		assertEquals(-1, prove(kernel(), new long[] { 1 }, null, true, false));
		assertEquals(-1, prove(kernel(), new long[] { 1 }, mock(NativeTermAuthority.class), true, false));
	}

	@Test
	void parallelInterpretedAndExternalCallbacksDecline() {
		assertEquals(-1, prove(kernel(), new long[] { 1, 2 }, identity(), false, false));
		assertEquals(-1, prove(kernel(), new long[] { 1, 2 }, identity(), true, true));
		assertEquals(-1, LmdbNativeKernelExecution.groupedRootSlot(null));
	}

	@Test
	void nestedRootOverwriteAndFrameRestoreDecline() {
		var overwrite = new LmdbNativeKernelIr.LeftGroup(List.of(new LmdbNativeKernelIr.Probe(1,
				LmdbNativeKernelIr.Operand.col(1), 0)));
		assertEquals(-1, prove(kernel(overwrite), new long[] { 1, 2 }, identity(), true, false));
		var restore = new LmdbNativeKernelIr.LeftGroup(List.of(new LmdbNativeKernelIr.Probe(1,
				LmdbNativeKernelIr.Operand.col(0), 2)), new int[] { 2 }, new int[] { 0 });
		assertEquals(-1, prove(kernel(restore), new long[] { 1, 2 }, identity(), true, false));
	}

	@Test
	void aliasAndEffectfulBindDecline() {
		assertEquals(-1, prove(kernel(new LmdbNativeKernelIr.BindAlias(LmdbNativeKernelIr.Operand.col(0), 2)),
				new long[] { 1, 2 }, identity(), true, false));
		assertEquals(-1, prove(kernel(new LmdbNativeKernelIr.BindHook(0, new LmdbNativeKernelIr.Operand[0], 2, true)),
				new long[] { 1, 2 }, identity(), true, false));
	}

	@Test
	void partitionRetainsExactResidualMembership() {
		var plan = NativeKernelGrouping.plan(null, new int[] { 0, 1 }, 0);
		try (var tracker = new NativeOrderedDistinctTracker(plan)) {
			assertTrue(tracker.add(new long[] { 1, 7 }));
			assertFalse(tracker.add(new long[] { 1, 7 }));
			assertTrue(tracker.add(new long[] { 1, 8 }));
			assertTrue(tracker.add(new long[] { 2, 7 }));
			assertFalse(tracker.add(new long[] { 2, 7 }));
		}
	}

	@Test
	void partitionRequiresProjectedRoot() {
		assertNull(NativeKernelGrouping.plan(null, new int[] { 5, 6 }, 4));
		assertNull(NativeKernelGrouping.plan(null, new int[] { 4, 5 }, -1));
		var plan = NativeKernelGrouping.plan(null, new int[] { 6, 4, 5 }, 4);
		assertEquals(NativeDistinctStrategy.PARTITIONED_HASH, plan.strategy);
		assertArrayEquals(new int[] { 6, 5 }, plan.residualSlots);
		assertEquals(NativeDistinctStrategy.ADJACENT, NativeKernelGrouping.plan(null, new int[] { 4 }, 4).strategy);
	}
}
